// Differential test runner: compares /output/test9.mjs against /workspace/dataset/test9_executable
// Usage:
//   node /workspace/dev/run.mjs                 -> run every case file under /workspace/dev/cases (recursive)
//   node /workspace/dev/run.mjs <dir-or-file>   -> run a subset
//   node /workspace/dev/run.mjs -v ...          -> show full expected/actual for failures
// Case files hold the RAW bytes passed as the value of --a (trailing newlines are significant).
import { spawnSync } from 'node:child_process';
import { readdirSync, statSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const EXE = '/workspace/dataset/test9_executable';
const ENTRY = '/output/test9.mjs';

function collect(p, out) {
  const st = statSync(p);
  if (st.isDirectory()) {
    for (const name of readdirSync(p).sort()) collect(join(p, name), out);
  } else if (p.endsWith('.txt')) out.push(p);
  return out;
}

function show(buf) {
  const s = buf.toString('utf8');
  let r = '';
  for (const ch of s) {
    if (ch === '\n') r += '\\n\n';
    else if (ch === '\t') r += '\\t';
    else if (ch === '\r') r += '\\r';
    else r += ch;
  }
  return r;
}

const argv = process.argv.slice(2);
const verbose = argv.includes('-v');
const targets = argv.filter((a) => a !== '-v');
const roots = targets.length ? targets : ['/workspace/dev/cases'];
const files = [];
for (const r of roots) collect(r, files);

let pass = 0;
const fails = [];
for (const f of files) {
  const arg = readFileSync(f, 'utf8');
  const exp = spawnSync(EXE, ['--a', arg], { encoding: 'buffer' });
  const got = spawnSync(process.execPath, [ENTRY, '--a', arg], { encoding: 'buffer' });
  const expOut = exp.stdout ?? Buffer.alloc(0);
  const gotOut = got.stdout ?? Buffer.alloc(0);
  const sameOut = expOut.equals(gotOut);
  const sameRc = exp.status === got.status;
  if (sameOut && sameRc) {
    pass++;
  } else {
    fails.push({ f, arg, expOut, gotOut, exp, got, sameOut, sameRc });
  }
}

for (const x of fails) {
  console.log('==== FAIL ' + x.f);
  console.log('  input   : ' + show(Buffer.from(x.arg, 'utf8')).split('\n').join('\n            '));
  console.log('  rc      : expected ' + x.exp.status + ' got ' + x.got.status);
  if (!x.sameOut || verbose) {
    console.log('  expected: ' + show(x.expOut).split('\n').join('\n            '));
    console.log('  actual  : ' + show(x.gotOut).split('\n').join('\n            '));
  }
  if (x.got.status !== 0) {
    const err = (x.got.stderr ?? Buffer.alloc(0)).toString('utf8');
    if (err.trim()) console.log('  js stderr: ' + err.trim().split('\n').slice(0, 8).join('\n             '));
  }
  if (x.exp.status !== 0 && verbose) {
    const err = (x.exp.stderr ?? Buffer.alloc(0)).toString('utf8');
    if (err.trim()) console.log('  py stderr: ' + err.trim().split('\n').slice(-6).join('\n             '));
  }
}
console.log('');
console.log(pass + '/' + files.length + ' passed, ' + fails.length + ' failed');
if (fails.length) process.exitCode = 1;
