import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test9_executable';
const f = process.argv[2];
const arg = readFileSync(f, 'utf8');
const r = spawnSync(EXE, ['--a', arg], { encoding: 'buffer' });
function vis(buf) {
  const s = buf.toString('utf8');
  let out = '';
  for (const ch of s) {
    if (ch === '\n') out += '$\n';
    else if (ch === '\t') out += '\\t';
    else if (ch === '\r') out += '\\r';
    else if (ch === ' ') out += '·';
    else out += ch;
  }
  return out;
}
process.stdout.write('RC=' + r.status + '\n');
process.stdout.write('--- stdout (· = space, $ = NL) ---\n');
process.stdout.write(vis(r.stdout ?? Buffer.alloc(0)));
process.stdout.write('--- end ---\n');
if (r.status !== 0) {
  const e = (r.stderr ?? Buffer.alloc(0)).toString('utf8').trim().split('\n');
  process.stdout.write('STDERR tail:\n' + e.slice(-5).join('\n') + '\n');
}

