import { writeFileSync, mkdirSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
const DIR = '/workspace/dev/cases/structure-integration';
mkdirSync(DIR, { recursive: true });
const EXE = '/workspace/dataset/test9_executable';
const L = (...lines) => lines.join('\n') + '\n';

export const cases = [];
export function C(name, doc, desc) { cases.push({ name, doc, desc }); }

export function emit(list) {
  const log = [];
  for (const c of list) {
    const p = DIR + '/' + c.name + '.txt';
    writeFileSync(p, c.doc, 'utf8');
    const r = spawnSync(EXE, ['--a', c.doc], { encoding: 'utf8' });
    log.push('##### ' + c.name + '  -- ' + c.desc);
    log.push('RC=' + r.status);
    log.push('IN : ' + JSON.stringify(c.doc));
    log.push('OUT: ' + JSON.stringify(r.stdout));
    if (r.status !== 0) log.push('ERRLINE: ' + (r.stderr.split('\n').filter((x) => /Error|error/.test(x))[0] || '?'));
    log.push('');
  }
  process.stdout.write(log.join('\n'));
}
export { L };

import { C, emit, L, cases } from './lib.mjs';
const NB = ' ';

// ---------- comments / whitespace / document markers ----------
C('58-comments-everywhere', L(
  '# leading comment',
  '#',
  '   # indented comment',
  'a: 1 # trailing',
  '# between keys',
  'b:  # after key with no value on this line',
  '  # comment before first item',
  '  - x   # item comment',
  '  # between items',
  '  - y',
  'c:',
  '  # only a comment then a nested map',
  '  d: 2 #d',
  'e: [1, 2] # after flow',
  'f: "# not a comment"',
  '# trailing comment at EOF',
), 'comments are dropped entirely; # inside quotes is data');

C('59-trailing-whitespace-lines', 'a: 1   \nb: two  \nc:   \n  d: 3 \n   \ne: [1, 2]  \n',
  'trailing SPACES (not tabs) on every line are legal and dropped; blank line of spaces ok');

C('60-blank-lines-everywhere', '\n\n\na: 1\n\n\nb: 2\n\n\nc:\n\n  d: 3\n\n\n',
  'blank lines anywhere are ignored');

C('61-doc-markers', '---\na: 1\nb: 2\n...\n',
  'explicit --- and ... in the input; single document -> ok');

C('62-yaml-directive', '%YAML 1.1\n---\na: 1\nb: [2, 3]\n',
  '%YAML 1.1 directive accepted, not reproduced on output');

C('63-tag-directive', '%TAG !e! tag:example.com,2000:\n---\na: 1\n',
  '%TAG directive accepted (unused handle) -> plain output');

C('64-crlf-document', 'a: 1\r\nb:\r\n  - x\r\n  - y\r\nc: |\r\n  l1\r\n  l2\r\n',
  'CRLF line endings normalised to \\n; block scalar content gets \\n only');

C('65-cr-only-document', 'a: 1\rb: 2\rc:\r  - x\r',
  'lone CR is a line break for the scanner');

C('66-bom-prefixed', '﻿a: 1\nb: 2\n',
  'leading U+FEFF BOM is stripped by the reader');

C('67-nbsp-not-indent', 'a:\n' + NB + ' b: 1\nc: 2\n',
  'U+00A0 is NOT whitespace for indentation: becomes part of the key -> "\\_ b"');

C('68-nbsp-in-values', 'a: "x' + NB + 'y"\nb: \'p' + NB + 'q\'\n',
  'NBSP inside a value forces double quotes with \\_ escape');

// ---------- special tags round-tripping ----------
C('69-set-tag', L(
  'plain_map: {a: 1}',
  'a_set: !!set',
  '  ? one',
  '  ? two',
  'z: end',
), '!!set becomes a Python set -> re-emitted as "!!set" tag + block map with null values; SET ORDER IS UNSPECIFIED (see spec note)');

C('70-omap-tag', L(
  'ordered: !!omap',
  '- b: 1',
  '- a: 2',
  '- c: 3',
), '!!omap -> list of Python tuples -> re-emitted as !!python/tuple items (yaml.dump uses the UNSAFE Dumper)');

C('71-pairs-tag', L(
  'pairs: !!pairs',
  '- a: 1',
  '- a: 2',
  '- b: 3',
), '!!pairs -> list of tuples -> !!python/tuple');

C('72-binary-tag', L(
  'blob: !!binary |',
  '  R0lGODlhDAAMAIQAAP//9/X17unp5WZmZgAAAOfn515eXvPz7Y6OjuDg4J+fn5',
  '  OTk6enp56enmlpaWNjY6Ojo4SEhP/++f/++f/++f/++f/++f/++f/++f/++f/+',
  '  +f/++f/++f/++f/++f/++SH+Dk1hZGUgd2l0aCBHSU1QACwAAAAADAAMAAAFLC',
  '  AgjoEwnuNAFOhpEMTRiggcz4BNJHrv/zCFcLiwMWYNG84BwwEeECcgggoBADs=',
  'text: hello',
), '!!binary -> Python bytes -> re-emitted as !!binary with 60-char base64 lines');

C('73-explicit-scalar-tags', L(
  'a: !!str 5',
  'b: !!int "7"',
  'c: !!float "8"',
  'd: !!bool "yes"',
  'e: !!null ""',
  'f: !!str ""',
  'g: !!timestamp 2001-12-14',
  'h: !!seq [1]',
  'i: !!map {x: 1}',
), 'explicit standard tags resolve to native types and are re-emitted implicitly');

// ---------- timestamps ----------
C('74-timestamps-mixed-with-strings', L(
  'date_only: 2001-12-14',
  'canonical: 2001-12-14T21:59:43.10-05:00',
  'space_sep: 2001-12-14 21:59:43.10 -5',
  'zulu: 2001-12-15T02:59:43.1Z',
  'no_tz: 2001-12-14 21:59:43',
  'no_frac_tz: 2001-12-14 21:59:43+03:30',
  'lower_t: 2001-12-14t21:59:43.10-05:00',
  'quoted: "2001-12-14"',
  'not_a_date: 2001-12-14x',
  'partial: 2001-12',
  'year: 2001',
  'time_only: 21:59:43',
), 'timestamps vs date-like strings; datetime is emitted "YYYY-MM-DD HH:MM:SS[.ffffff][+HH:MM]"');

C('75-timestamp-keys', L(
  '2001-12-15: b',
  '2001-12-14: a',
  '2000-01-01: c',
), 'date keys sort chronologically; emitted plain');

C('76-timestamp-date-datetime-keys', L(
  '2001-12-14: date',
  '2001-12-14 10:00:00: datetime',
  '2001-12-13: earlier',
), 'date and datetime keys are NOT comparable in Python -> TypeError -> insertion order');

// ---------- long / mixed sequences ----------
C('77-long-mixed-seq', L(
  ...['1', '2.5', 'true', 'false', 'null', '~', 'abc', "'123'", '0x10', '017',
    '1e10', '1.0e+10', '.inf', '-.inf', '.nan', '2001-12-14', "''", "' '", '{}', '[]',
    '{a: 1}', '[1, 2]', 'yes', 'off', 'On', 'NO', 'y', 'n', '-0', '+0',
    '3:00', '1_2_3', '0b11', '0o7', '0xFF', 'a b c', "'a: b'", '"x\\ty"', 'None', 'nil'].map((v) => '- ' + v),
), '40-element sequence covering every scalar flavour');

C('78-hundred-item-seq', L(...Array.from({ length: 100 }, (_, i) => '- item' + (i + 1))),
  '100 short items; verifies no width/fold interaction in seqs');

C('79-seq-of-30-maps', L(...Array.from({ length: 30 }, (_, i) =>
  '- {id: ' + (i + 1) + ', name: n' + (i + 1) + ', on: ' + (i % 2 === 0) + '}')),
  '30 flow maps in a block seq; "on" key becomes true');

// ---------- failure cases (deliberate, non-zero exit) ----------
C('80-FAIL-multi-document', '---\na: 1\n---\nb: 2\n',
  'FAILS rc=1: ComposerError "expected a single document in the stream"');

C('81-FAIL-tab-indent', 'a:\n\tb: 1\n',
  'FAILS rc=1: ScannerError - tab cannot start a token');

C('82-FAIL-trailing-tab', 'a: 1\t\n',
  'FAILS rc=1: ScannerError - trailing TAB after a plain scalar');

C('83-FAIL-unhashable-key', '? [a, b]\n: v\n',
  'FAILS rc=1: ConstructorError "found unhashable key" (sequence used as key)');

C('84-FAIL-bad-month', 'd: 2001-13-14\n',
  'FAILS rc=1: ValueError "month must be in 1..12" (resolver matched, constructor threw)');

C('85-FAIL-unknown-tag', 'a: !!foo bar\n',
  'FAILS rc=1: ConstructorError "could not determine a constructor"');

C('86-FAIL-undefined-alias', 'a: *nope\n',
  'FAILS rc=1: ComposerError "found undefined alias"');

C('87-FAIL-duplicate-anchor', 'a: &x 1\nb: &x 2\nc: *x\n',
  'FAILS rc=1: ComposerError "found duplicate anchor"');

C('88-FAIL-python-tag', 'a: !!python/object:os.system {}\n',
  'FAILS rc=1: safe_load rejects python tags');

C('89-FAIL-bad-indent', 'a: 1\n b: 2\n',
  'FAILS rc=1: ScannerError/ParserError from bad indentation');

emit(cases);

